.venv/bin/python - <<'EOF'
import csv, json
from pathlib import Path
b = Path("data/outputs-recovery/preflight/preflight-2")
h = [json.loads(l) for l in open(b / "harness.jsonl")]
def ev(name): return [e for e in h if e["event"] == name]
def f(x):
    try: return f"{float(x):.1f}"
    except (TypeError, ValueError): return x
print("pos case claims exec compl detection rerun finish overhead wasted | timeliness met q3a | hostGiB")
for r in csv.DictReader(open(b / "injections.csv")):
    hm = r.get("host_available_bytes")
    print(r["position"], r["case"].ljust(3), r["claims"], r["executions"], r["complete_executions"], *(f(r[k]) for k in ("detection_s", "rerun_s", "finish_s", "overhead_s", "wasted_step_s")),
          "|", r["timeliness"], r["deadline_met"], r["q3a_verdict"], "|", f(int(hm) / 2**30) if hm else None)
v = json.load(open(b / "validity.json"))
print("c0 median s:", f(v["c0_median_s"]), "| clock ts-mono s:", round(v["validity"]["clock"]["ts_minus_mono_s"], 4), "| processes on one clock:", v["validity"]["clock"]["processes_on_the_same_clock"], "| identity records:", v["validity"]["code_identity"]["records"])
print("accepted checks clean:", sum(not a["problems"] for a in v["outcomes"]["accepted_attempts"]), "of", len(v["outcomes"]["accepted_attempts"]))
print("liveness:", v["outcomes"]["liveness"])
print("nothing_left:", v["outcomes"]["nothing_left"], "| cleanup:", v["outcomes"]["cleanup_listing"])
print("batch peaks:", {s: (p["peak_bytes"] and round(p["peak_bytes"] / 2**20), p["limit_bytes"] and round(p["limit_bytes"] / 2**20), p["readings"], p["incomplete"]) for s, p in v["outcomes"]["batch_peaks"].items()})
print("host memory:", {k: (round(val / 2**30, 2) if isinstance(val, int) and k.endswith("bytes") else val) for k, val in v["outcomes"]["host_memory"].items()})
print("services_up s:", round(ev("services_up")[0]["seconds"], 1))
for r in ev("reference_step"): print("reference", r["step"], "exit", r["exit"], "s", round(r["after"] - r["before"], 1))
for p in ev("process_started"): print("start", p["name"], "same_clock", p["same_clock"], "s", round(p["after"] - p["before"], 1))
for i in ev("injection"):
    extra = {k: i[k] for k in ("seconds", "ready", "restored", "t_inj", "resumed", "fenced_mono", "stopped", "held_mono") if k in i}
    if "restored" in extra: extra["restore_after_inj_s"] = round(extra["restored"] - extra["t_inj"], 1)
    if "ready" in extra: extra["ready_after_inj_s"] = round(extra["ready"] - extra["t_inj"], 1)
    if "resumed" in extra: extra["resumed_after_inj_s"] = round(extra["resumed"] - extra["t_inj"], 1)
    if "fenced_mono" in extra: extra["fenced_after_inj_s"] = round(extra["fenced_mono"] - extra["t_inj"], 1)
    print("inj", i["position"], i["case"], i.get("kind"), {k: v2 for k, v2 in extra.items() if k.endswith("_s") or k in ("seconds", "stopped")})
EOF

